      (function () {
        "use strict";
        var PDFLib = window.PDFLib;
        var pdfjsLib = window.pdfjsLib;
        if (pdfjsLib) {
          /* Der pdf.js-Worker-Code wird als separates Skript
             (vendor/pdf.worker.min.js) geladen und liegt dadurch als window.pdfjsWorker
             direkt im Haupt-Thread vor. pdf.js erkennt das und nutzt ihn
             ohne echten Web-Worker („Fake Worker"): Es wird kein Worker
             gestartet und nichts per Blob-Adresse nachgeladen.
             Genau dieser Worker-Start war der Fehler beim Hochladen:
             In Handy-Ansichten (WebView, Sandbox-iframe, lokale Datei)
             sind Worker aus Blob-Adressen („blob:null/…") blockiert,
             der pdf.js-Start schlug fehl – und weil das Laden der Datei
             davon abhing, wurde die ganze PDF abgelehnt, obwohl der
             Button und die Dateiauswahl funktionierten.
             Nur falls das eingebettete Worker-Skript ausnahmsweise fehlt,
             bleibt der alte Blob-Weg als Rückfall erhalten. */
          var mainThreadWorker = !!(window.pdfjsWorker && window.pdfjsWorker.WorkerMessageHandler);
          if (!mainThreadWorker) {
            try {
              var wsrcEl = document.getElementById("pdfjsWorkerSource");
              var wsrcTxt = wsrcEl ? wsrcEl.textContent : "";
              if (wsrcTxt && wsrcTxt.length > 1000) {
                pdfjsLib.GlobalWorkerOptions.workerSrc =
                  URL.createObjectURL(new Blob([wsrcTxt], { type: "text/javascript" }));
              }
            } catch (e) { /* Rückfall unten greift */ }
          }
          if (!pdfjsLib.GlobalWorkerOptions.workerSrc) {
            pdfjsLib.GlobalWorkerOptions.workerSrc = "vendor/pdf.worker.min.js";
          }
        }

        /* ---------------- C++ engine: QPDF compiled to WebAssembly ----------------
           QPDF is a professional PDF engine written in C++. The build in
           data:application/javascript;base64, + qpdf.wasm runs it directly in the browser,
           so merging, deleting, rotating and re-saving happens locally. */
        var qpdfFactory = (typeof window.Module === "function") ? window.Module : null;
        var engineState = "loading"; /* loading | ready | fallback */

        function setEngine(state) {
          engineState = state;
          var dotCls = state === "ready" ? "engdot ok" : (state === "fallback" ? "engdot fb" : "engdot load");
          var txt = state === "ready" ? "C++-Engine bereit (QPDF · WebAssembly)"
            : state === "fallback" ? "Reserve-Engine aktiv"
            : "C++-Engine lädt …";
          document.querySelectorAll("[data-engdot]").forEach(function (d) { d.className = dotCls; });
          document.querySelectorAll("[data-engtext]").forEach(function (t) { t.textContent = txt; });
        }

        var qpdfWasmBlobUrl = null;
        function getQpdfWasmUrl() {
          return "vendor/qpdf.wasm";
        }

        function newQpdf() {
          return qpdfFactory({
            locateFile: function (path) {
              if (path.slice(-5) === ".wasm") {
                /* Das C++-Modul (qpdf.wasm) ist als Base64 in dieser Datei
                   eingebettet und wird per Blob-URL geladen – so läuft die
                   C++-Engine auch als einzelne lokale Datei (file://),
                   wo fetch/XHR auf Nachbar-Dateien blockiert ist. */
                return getQpdfWasmUrl() || "vendor/qpdf.wasm";
              }
              return path;
            },
            print: function () {},
            printErr: function () {}
          });
        }

        var engineProbe = null;
        if (qpdfFactory) {
          engineProbe = withTimeout(newQpdf(), 8000).then(
            function () { setEngine("ready"); return true; },
            function () { setEngine("fallback"); return false; }
          );
        } else {
          setEngine("fallback");
        }

        /* One qpdf CLI run on a fresh engine instance.
           inputs: {name: Uint8Array}; resolves with the bytes of /out.pdf. */
        function runQpdf(args, inputs) {
          return newQpdf().then(function (mod) {
            Object.keys(inputs).forEach(function (name) {
              mod.FS.writeFile("/" + name, inputs[name]);
            });
            var rc = mod.callMain(args);
            if (rc !== 0) throw new Error("qpdf exit code " + rc);
            return mod.FS.readFile("/out.pdf");
          });
        }

        var uid = 0;
        function nextId() { return ++uid; }

        var files = new Map();   // fileId -> {id, name, libDoc, jsDoc, pageCount, sizes:[]}
        var pages = [];          // {id, fileId|null, pageIndex, extraRot, blankW, blankH}
        var selected = new Set();

        var els = {
          input: document.getElementById("fileInput"),
          grid: document.getElementById("grid"),
          empty: document.getElementById("emptyState"),
          dropzone: document.getElementById("dropzone"),
          statusbar: document.getElementById("statusbar"),
          statFiles: document.getElementById("statFiles"),
          statPages: document.getElementById("statPages"),
          statSel: document.getElementById("statSel"),
          statSelWrap: document.getElementById("statSelWrap"),
          filebar: document.getElementById("filebar"),
          chips: document.getElementById("chips"),
          toast: document.getElementById("toast"),
          busy: document.getElementById("busy"),
          busyText: document.getElementById("busyText"),
          btnAdd: document.getElementById("btnAdd"),
          btnPick: document.getElementById("btnPick"),
          btnBlank: document.getElementById("btnBlank"),
          btnSelectAll: document.getElementById("btnSelectAll"),
          btnRotateSel: document.getElementById("btnRotateSel"),
          btnDeleteSel: document.getElementById("btnDeleteSel"),
          btnExtract: document.getElementById("btnExtract"),
          btnDownload: document.getElementById("btnDownload"),
          dlpanel: document.getElementById("dlpanel"),
          dlName: document.getElementById("dlName"),
          dlSub: document.getElementById("dlSub"),
          dlShare: document.getElementById("dlShare"),
          dlSave: document.getElementById("dlSave"),
          dlOpen: document.getElementById("dlOpen"),
          dlClose: document.getElementById("dlClose"),
          btnTxJump: document.getElementById("btnTxJump"),
          txPanel: document.getElementById("txPanel"),
          rsPanel: document.getElementById("rsPanel"),
          homeView: document.getElementById("homeView"),
          homeLoaded: document.getElementById("homeLoaded"),
          viewbar: document.getElementById("viewbar"),
          viewTitle: document.getElementById("viewTitle"),
          btnHome: document.getElementById("btnHome"),
          btnOther: document.getElementById("btnOther"),
          rsOptimize: document.getElementById("rsOptimize"),
          rsInfo: document.getElementById("rsInfo"),
          rsResult: document.getElementById("rsResult"),
          txOcr: document.getElementById("txOcr"),
          txSearch: document.getElementById("txSearch"),
          txSearchBtn: document.getElementById("txSearchBtn"),
          txDownloadTxt: document.getElementById("txDownloadTxt"),
          txNote: document.getElementById("txNote"),
          txProgress: document.getElementById("txProgress"),
          txProgressText: document.getElementById("txProgressText"),
          txSearchBlock: document.getElementById("txSearchBlock"),
          txSearchResults: document.getElementById("txSearchResults"),
          txPages: document.getElementById("txPages")
        };

        var toastTimer = null;
        function toast(msg, isErr) {
          els.toast.textContent = msg;
          els.toast.className = "toast show" + (isErr ? " err" : "");
          clearTimeout(toastTimer);
          toastTimer = setTimeout(function () { els.toast.className = "toast"; }, 3400);
        }
        function setBusy(on, text) {
          if (text) els.busyText.textContent = text;
          els.busy.className = "busy" + (on ? " show" : "");
        }

        /* ---------------- File loading ----------------
           Die Auswahl-Buttons sind <label for="fileInput">: Ein Tipp
           aktiviert das Dateifeld nativ als direkte Reaktion auf den
           Tipp, ganz ohne JavaScript-Klick – das funktioniert auch in
           Handy-Ansichten und WebViews, die einen Skript-Klick auf ein
           Dateifeld still ignorieren. Für die Tastatur sind die Labels
           fokussierbar und öffnen die Auswahl per Enter/Leertaste. */
        function openPicker() { els.input.click(); }
        [els.btnAdd, els.btnPick].forEach(function (lbl) {
          lbl.addEventListener("keydown", function (e) {
            if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openPicker(); }
          });
        });
        els.input.addEventListener("click", function () {
          /* Wert bei jedem Öffnen leeren, damit dieselbe Datei erneut
             gewählt werden kann und "change" sicher auslöst. */
          els.input.value = "";
        });
        els.dropzone.addEventListener("click", function (e) {
          /* Tipp irgendwo in die Ablagefläche öffnet die Auswahl;
             Tipp auf das Label selbst löst bereits nativ aus. */
          if (e.target && e.target.closest && e.target.closest("label, a, button")) return;
          openPicker();
        });
        els.input.addEventListener("change", function () {
          if (els.input.files && els.input.files.length) loadFiles(els.input.files);
        });

        ["dragenter", "dragover"].forEach(function (ev) {
          document.addEventListener(ev, function (e) {
            e.preventDefault();
            if (e.dataTransfer && Array.prototype.indexOf.call(e.dataTransfer.types || [], "Files") !== -1) {
              els.dropzone.classList.add("over");
            }
          });
        });
        ["dragleave", "drop"].forEach(function (ev) {
          document.addEventListener(ev, function (e) {
            e.preventDefault();
            if (ev === "dragleave" && e.relatedTarget) return;
            els.dropzone.classList.remove("over");
          });
        });
        document.addEventListener("drop", function (e) {
          var dt = e.dataTransfer;
          if (dt && dt.files && dt.files.length) loadFiles(dt.files);
        });

        function loadFiles(fileList) {
          var list = Array.prototype.slice.call(fileList);
          var pdfs = list.filter(function (f) {
            return f.type === "application/pdf" || /\.pdf$/i.test(f.name);
          });
          if (!pdfs.length) { toast("Das war keine PDF-Datei.", true); return; }
          var skipped = list.length - pdfs.length;
          setBusy(true, "PDFs werden geladen …");
          var chain = Promise.resolve();
          var errors = [];
          pdfs.forEach(function (f) {
            chain = chain.then(function () { return addFile(f).catch(function () { errors.push(f.name); }); });
          });
          chain.then(function () {
            setBusy(false);
            if (errors.length) {
              toast("Konnte nicht gelesen werden (evtl. passwortgeschützt): " + errors.join(", "), true);
            } else {
              toast(pdfs.length === 1 ? "1 PDF geladen." : pdfs.length + " PDFs geladen.");
            }
            if (skipped > 0) toast(skipped + " Datei(en) übersprungen – nur PDFs möglich.", true);
            refresh();
          });
        }

        function withTimeout(p, ms) {
          return Promise.race([p, new Promise(function (resolve, reject) {
            setTimeout(function () { reject(new Error("timeout")); }, ms);
          })]);
        }

        /* pdf.js wird nur für die Seitenvorschau gebraucht und läuft im
           Hintergrund nach. Das Laden einer Datei hängt NICHT mehr davon
           ab: pdf-lib (reines JavaScript, kein Worker) meldet die Datei
           sofort an. Schlägt die Vorschau fehl, zeigt die Karte einen
           Platzhalter – die Datei und alle Bearbeitungs-Funktionen
           (Löschen, Drehen, Sortieren, Speichern per C++-Engine) gehen
           trotzdem. Früher hing alles an einem Versprechen: Ein einziger
           pdf.js-Fehler (z. B. blockierter Worker auf dem Handy) ließ
           die komplette PDF als „nicht lesbar" scheitern. */
        function startJsDoc(rec, buf) {
          if (!pdfjsLib) {
            rec.jsDocPromise = Promise.reject(new Error("pdf.js fehlt"));
            return;
          }
          var docOpts = { data: buf, cMapPacked: true };
          if (/^https?:$/.test(location.protocol)) {
            /* CMap- und Standard-Schrift-Ordner liegen nur bei, wenn
               die Seite über HTTP ausgeliefert wird. Eine einzelne
               lokale Datei (file://) darf sie per Browser-Regeln nicht
               nachladen, darum werden sie dort weggelassen und pdf.js
               nutzt seine eingebauten Rückfall-Schriften. */
            docOpts.standardFontDataUrl = "vendor/standard_fonts/";
            docOpts.cMapUrl = "vendor/cmaps/";
          }
          rec.jsDocPromise = withTimeout(pdfjsLib.getDocument(docOpts).promise, 20000).then(function (jsDoc) {
            if (!files.has(rec.id)) { jsDoc.destroy(); return jsDoc; }
            rec.jsDoc = jsDoc;
            return jsDoc;
          });
          /* Fehler hier sind kein Ladefehler der Datei – nur die
             Vorschau bleibt dann ein Platzhalter. Abfangen, damit kein
             unbehandelter Promise-Fehler entsteht. */
          rec.jsDocPromise.catch(function () {});
        }

        function addFile(file) {
          return withTimeout(file.arrayBuffer().then(function (buf) {
            return PDFLib.PDFDocument.load(buf.slice(0), { ignoreEncryption: false }).then(function (libDoc) {
              var fid = nextId();
              var sizes = libDoc.getPages().map(function (p) {
                var s = p.getSize(); return { w: s.width, h: s.height };
              });
              var rec = { id: fid, name: file.name, bytes: new Uint8Array(buf.slice(0)), libDoc: libDoc, jsDoc: null, jsDocPromise: null, pageCount: libDoc.getPageCount(), sizes: sizes };
              files.set(fid, rec);
              for (var i = 0; i < libDoc.getPageCount(); i++) {
                pages.push({ id: nextId(), fileId: fid, pageIndex: i, extraRot: 0 });
              }
              startJsDoc(rec, buf.slice(0));
            });
          }), 30000);
        }

        /* ---------------- Rendering ---------------- */
        var ICONS = {
          check: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>',
          grip: '<svg viewBox="0 0 24 24" fill="currentColor"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></svg>',
          rotL: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 0 2.64-6.36"/><path d="M3 3v6h6"/></svg>',
          rotR: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-2.64-6.36"/><path d="M21 3v6h-6"/></svg>',
          left: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m15 18-6-6 6-6"/></svg>',
          right: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m9 18 6-6-6-6"/></svg>',
          trash: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>',
          x: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>'
        };

        function buildCard(pg) {
          var card = document.createElement("article");
          card.className = "card";
          card.dataset.id = pg.id;

          var thumb = document.createElement("div");
          thumb.className = "thumb";
          thumb.title = "Klicken zum Auswählen";

          var pos = document.createElement("span");
          pos.className = "pos";
          thumb.appendChild(pos);

          var pick = document.createElement("button");
          pick.type = "button";
          pick.className = "pick";
          pick.setAttribute("aria-label", "Seite auswählen");
          pick.innerHTML = ICONS.check;
          thumb.appendChild(pick);

          if (pg.fileId === null) {
            var bp = document.createElement("div");
            bp.className = "blankpage";
            bp.textContent = "LEER";
            thumb.appendChild(bp);
          } else {
            var spin = document.createElement("div");
            spin.className = "spin";
            thumb.appendChild(spin);
            renderThumb(pg, thumb, spin);
          }
          card.appendChild(thumb);

          var meta = document.createElement("div");
          meta.className = "meta";
          var fn = document.createElement("div"); fn.className = "fn";
          var pn = document.createElement("div"); pn.className = "pn";
          if (pg.fileId === null) {
            fn.textContent = "Leere Seite";
            pn.textContent = "eingefügt";
          } else {
            var f = files.get(pg.fileId);
            fn.textContent = f ? f.name : "";
            fn.title = fn.textContent;
            pn.textContent = "Seite " + (pg.pageIndex + 1) + " von " + (f ? f.pageCount : "?");
          }
          meta.appendChild(fn); meta.appendChild(pn);
          card.appendChild(meta);

          var act = document.createElement("div");
          act.className = "cactions";
          function mkBtn(icon, label, cls, fn2) {
            var b = document.createElement("button");
            b.type = "button"; b.className = "cbtn " + (cls || "");
            b.innerHTML = icon; b.title = label; b.setAttribute("aria-label", label);
            b.addEventListener("click", function (e) { e.stopPropagation(); fn2(); });
            return b;
          }
          var grip = document.createElement("span");
          grip.className = "cbtn grip"; grip.innerHTML = ICONS.grip;
          grip.title = "Ziehen zum Sortieren (oder Seite gedrückt halten)";
          act.appendChild(grip);
          act.appendChild(mkBtn(ICONS.left, "Nach vorne", "", function () { movePage(pg.id, -1); }));
          act.appendChild(mkBtn(ICONS.right, "Nach hinten", "", function () { movePage(pg.id, 1); }));
          act.appendChild(mkBtn(ICONS.rotL, "Links drehen", "", function () { rotatePage(pg, -90); }));
          act.appendChild(mkBtn(ICONS.rotR, "Rechts drehen", "", function () { rotatePage(pg, 90); }));
          act.appendChild(mkBtn(ICONS.trash, "Seite löschen", "del", function () { deletePages([pg.id]); }));
          card.appendChild(act);

          thumb.addEventListener("click", function () {
            if (Date.now() < suppressClickUntil) return;
            toggleSelect(pg.id);
          });
          pick.addEventListener("click", function (e) { e.stopPropagation(); toggleSelect(pg.id); });

          setupDrag(card, grip, pg);
          return card;
        }

        function renderThumb(pg, thumb, spin) {
          var f = files.get(pg.fileId);
          if (!f) { spin.remove(); return; }
          /* Die Vorschau wartet auf das pdf.js-Dokument aus dem
             Hintergrund-Laden (startJsDoc). Gibt es keins, greift der
             Fehlerzweig unten und zeigt den Platzhalter. */
          var docReady = f.jsDoc ? Promise.resolve(f.jsDoc)
            : (f.jsDocPromise || Promise.reject(new Error("Keine Vorschau möglich")));
          docReady.then(function (jsDoc) {
            return jsDoc.getPage(pg.pageIndex + 1);
          }).then(function (page) {
            var baseVp = page.getViewport({ scale: 1, rotation: 0 });
            var targetW = 300;
            var scale = targetW / baseVp.width;
            var vp = page.getViewport({ scale: scale, rotation: (page.rotate + pg.extraRot) % 360 });
            var canvas = document.createElement("canvas");
            canvas.width = Math.floor(vp.width);
            canvas.height = Math.floor(vp.height);
            var ctx = canvas.getContext("2d");
            return page.render({ canvasContext: ctx, viewport: vp }).promise.then(function () {
              spin.remove();
              thumb.insertBefore(canvas, thumb.children[2] || null);
              pg._canvas = canvas;
            });
          }).catch(function () {
            spin.remove();
            var d = document.createElement("div");
            d.className = "blankpage"; d.textContent = "Vorschau fehlt";
            thumb.appendChild(d);
          });
        }

        function rerenderThumb(pg) {
          var card = cardEl(pg.id);
          if (!card || pg.fileId === null) return;
          var thumb = card.querySelector(".thumb");
          var old = thumb.querySelector("canvas");
          if (old) old.remove();
          var spin = document.createElement("div");
          spin.className = "spin";
          thumb.appendChild(spin);
          renderThumb(pg, thumb, spin);
        }

        function cardEl(id) { return els.grid.querySelector('.card[data-id="' + id + '"]'); }

        /* ---------------- Sortieren: gedrückt halten & ziehen ----------------
           HTML5-Drag-&-Drop kennt keine Touch-Gesten – auf dem Handy tat
           sich damit gar nichts. Darum läuft das Sortieren jetzt über
           Pointer Events: Seite (Vorschau oder Griff) gedrückt halten,
           bis sie sich abhebt, dann mit Finger oder Maus an die neue
           Stelle ziehen und loslassen. Ein kurzes Tippen bleibt die
           Auswahl, ein Wischen bleibt das Scrollen: Erst wenn der Finger
           ruhig liegen bleibt, startet der Zieh-Modus. Am Griff startet
           das Ziehen sofort bei Bewegung, ganz ohne Halten. */
        var pressState = null;
        var dragState = null;
        var suppressClickUntil = 0;

        function setupDrag(card, grip, pg) {
          var thumb = card.querySelector(".thumb");
          thumb.addEventListener("pointerdown", function (e) { startPress(e, card, pg, false); });
          grip.addEventListener("pointerdown", function (e) { startPress(e, card, pg, true); });
          card.addEventListener("dragstart", function (e) { e.preventDefault(); });
          card.addEventListener("contextmenu", function (e) {
            if (pressState || dragState) e.preventDefault();
          });
        }

        function startPress(e, card, pg, fromGrip) {
          if (dragState || pressState) return;
          if (e.button !== undefined && e.button > 0) return;
          if (e.target && e.target.closest && e.target.closest("button")) return;
          var ps = { card: card, pg: pg, fromGrip: fromGrip, startX: e.clientX, startY: e.clientY, timer: null };
          pressState = ps;
          card.classList.add("pressing");
          function detach() {
            document.removeEventListener("pointermove", onMove, true);
            document.removeEventListener("pointerup", cancel, true);
            document.removeEventListener("pointercancel", cancel, true);
          }
          function cancel() {
            if (pressState !== ps) return;
            pressState = null;
            clearTimeout(ps.timer);
            card.classList.remove("pressing");
            detach();
          }
          function onMove(ev) {
            var dx = ev.clientX - ps.startX, dy = ev.clientY - ps.startY;
            if (Math.sqrt(dx * dx + dy * dy) < (fromGrip ? 5 : 10)) return;
            if (fromGrip) {
              pressState = null;
              clearTimeout(ps.timer);
              detach();
              beginDrag(ps);
              onDragMove(ev);
            } else {
              /* Finger bewegt sich vor dem Halten = Scrollen, kein Ziehen. */
              cancel();
            }
          }
          document.addEventListener("pointermove", onMove, true);
          document.addEventListener("pointerup", cancel, true);
          document.addEventListener("pointercancel", cancel, true);
          if (!fromGrip) {
            ps.timer = setTimeout(function () {
              if (pressState !== ps) return;
              pressState = null;
              detach();
              beginDrag(ps);
            }, 320);
          }
        }

        function blockScroll(e) { if (dragState) e.preventDefault(); }

        function beginDrag(ps) {
          var card = ps.card;
          var r = card.getBoundingClientRect();
          var ds = {
            card: card, pg: ps.pg,
            startX: ps.startX, startY: ps.startY,
            origNext: card.nextSibling,
            ph: document.createElement("div")
          };
          ds.ph.className = "card-placeholder";
          ds.ph.style.height = r.height + "px";
          card.parentNode.insertBefore(ds.ph, card);
          card.classList.remove("pressing");
          card.classList.add("drag-float");
          card.style.width = r.width + "px";
          card.style.left = r.left + "px";
          card.style.top = r.top + "px";
          card.style.transform = "rotate(-1.2deg) scale(1.03)";
          card.style.touchAction = "none";
          dragState = ds;
          els.grid.classList.add("is-dragging");
          if (navigator.vibrate) { try { navigator.vibrate(12); } catch (err) {} }
          document.addEventListener("pointermove", onDragMove, true);
          document.addEventListener("pointerup", onDragUp, true);
          document.addEventListener("pointercancel", onDragCancel, true);
          document.addEventListener("keydown", onDragKey, true);
          document.addEventListener("touchmove", blockScroll, { passive: false });
        }

        function onDragMove(e) {
          var ds = dragState;
          if (!ds) return;
          e.preventDefault();
          var x = e.clientX, y = e.clientY;
          ds.card.style.transform =
            "translate(" + (x - ds.startX) + "px," + (y - ds.startY) + "px) rotate(-1.2deg) scale(1.03)";
          /* Am Bildschirmrand weiter scrollen, damit auch ferne
             Positionen erreichbar sind. */
          if (y < 76) window.scrollBy(0, -14);
          else if (y > window.innerHeight - 76) window.scrollBy(0, 14);
          /* Zielposition in Lese-Reihenfolge (Zeilen, dann Spalten):
             Der Platzhalter wandert live mit, die Lücke zeigt immer,
             wo die Seite beim Loslassen landet. */
          var others = Array.prototype.filter.call(els.grid.children, function (c) {
            return c !== ds.card && c !== ds.ph;
          });
          var count = 0;
          others.forEach(function (c) {
            var cr = c.getBoundingClientRect();
            var cx = cr.left + cr.width / 2, cy = cr.top + cr.height / 2;
            if (cy < y - cr.height * 0.25 || (Math.abs(cy - y) <= cr.height * 0.5 && cx < x)) count++;
          });
          var target = count >= others.length ? null : others[count];
          if (target) { if (target.previousElementSibling !== ds.ph) els.grid.insertBefore(ds.ph, target); }
          else if (ds.ph !== els.grid.lastElementChild) els.grid.appendChild(ds.ph);
        }

        function onDragUp() { endDrag(true); }
        function onDragCancel() { endDrag(true); }
        function onDragKey(e) { if (e.key === "Escape") endDrag(false); }

        function endDrag(commit) {
          var ds = dragState;
          if (!ds) return;
          dragState = null;
          document.removeEventListener("pointermove", onDragMove, true);
          document.removeEventListener("pointerup", onDragUp, true);
          document.removeEventListener("pointercancel", onDragCancel, true);
          document.removeEventListener("keydown", onDragKey, true);
          document.removeEventListener("touchmove", blockScroll);
          els.grid.classList.remove("is-dragging");
          if (!commit) {
            /* Abgebrochen (Esc): Platzhalter zurück an die alte Stelle. */
            if (ds.origNext && ds.origNext.parentNode === els.grid && ds.origNext !== ds.ph) {
              els.grid.insertBefore(ds.ph, ds.origNext);
            } else if (!ds.origNext) {
              els.grid.appendChild(ds.ph);
            }
          }
          ds.ph.parentNode.replaceChild(ds.card, ds.ph);
          var card = ds.card;
          card.classList.remove("drag-float");
          card.style.width = "";
          card.style.left = "";
          card.style.top = "";
          card.style.transform = "";
          card.style.touchAction = "";
          /* Der Klick, der direkt nach dem Loslassen durchschlägt,
             darf die Seite nicht gleich wieder auswählen/abwählen. */
          suppressClickUntil = Date.now() + 300;
          if (commit) syncOrderFromDom();
        }
        function syncOrderFromDom() {
          var order = Array.prototype.map.call(els.grid.children, function (c) { return Number(c.dataset.id); });
          pages.sort(function (a, b) { return order.indexOf(a.id) - order.indexOf(b.id); });
          renumber();
        }

        /* ---------------- Page operations ---------------- */
        function toggleSelect(id) {
          if (selected.has(id)) selected.delete(id); else selected.add(id);
          var c = cardEl(id);
          if (c) c.classList.toggle("selected", selected.has(id));
          refreshStats();
        }
        function rotatePage(pg, deg) {
          pg.extraRot = ((pg.extraRot + deg) % 360 + 360) % 360;
          rerenderThumb(pg);
        }
        function movePage(id, dir) {
          var i = pages.findIndex(function (p) { return p.id === id; });
          var j = i + dir;
          if (i < 0 || j < 0 || j >= pages.length) return;
          var tmp = pages[i]; pages[i] = pages[j]; pages[j] = tmp;
          var a = cardEl(pages[j].id), b = cardEl(pages[i].id);
          if (a && b) { if (dir < 0) b.before(a); else b.after(a); }
          renumber();
        }
        function deletePages(ids) {
          if (!ids.length) return;
          var set = new Set(ids);
          pages = pages.filter(function (p) { return !set.has(p.id); });
          ids.forEach(function (id) {
            selected.delete(id);
            var c = cardEl(id); if (c) c.remove();
          });
          toast(ids.length === 1 ? "Seite gelöscht." : ids.length + " Seiten gelöscht.");
          refresh();
        }
        function removeFile(fid) {
          var f = files.get(fid);
          var ids = pages.filter(function (p) { return p.fileId === fid; }).map(function (p) { return p.id; });
          pages = pages.filter(function (p) { return p.fileId !== fid; });
          ids.forEach(function (id) { selected.delete(id); var c = cardEl(id); if (c) c.remove(); });
          if (f && f.jsDoc) f.jsDoc.destroy();
          Object.keys(nativeLinesCache).forEach(function (k) {
            if (k.indexOf(fid + ":") === 0) delete nativeLinesCache[k];
          });
          Object.keys(ocrCache).forEach(function (k) {
            if (k.indexOf(fid + ":") === 0) delete ocrCache[k];
          });
          ids.forEach(function (id) { delete pageTextData[id]; });
          files.delete(fid);
          toast("Datei entfernt.");
          refresh();
        }

        els.btnBlank.addEventListener("click", function () {
          var w = 595.28, h = 841.89;
          var last = pages[pages.length - 1];
          if (last) {
            if (last.fileId === null) { w = last.blankW; h = last.blankH; }
            else { var f = files.get(last.fileId); if (f) { var s = f.sizes[last.pageIndex]; w = s.w; h = s.h; } }
          }
          var pg = { id: nextId(), fileId: null, pageIndex: -1, extraRot: 0, blankW: w, blankH: h };
          pages.push(pg);
          els.grid.appendChild(buildCard(pg));
          refresh();
          toast("Leere Seite eingefügt.");
        });

        els.btnSelectAll.addEventListener("click", function () {
          if (selected.size === pages.length) {
            selected.clear();
          } else {
            pages.forEach(function (p) { selected.add(p.id); });
          }
          els.grid.querySelectorAll(".card").forEach(function (c) {
            c.classList.toggle("selected", selected.has(Number(c.dataset.id)));
          });
          refreshStats();
        });
        els.btnRotateSel.addEventListener("click", function () {
          pages.forEach(function (p) { if (selected.has(p.id)) rotatePage(p, 90); });
        });
        els.btnDeleteSel.addEventListener("click", function () {
          deletePages(Array.from(selected));
        });
        document.addEventListener("keydown", function (e) {
          if ((e.key === "Delete" || e.key === "Backspace") && selected.size &&
              !/INPUT|TEXTAREA/.test(document.activeElement.tagName)) {
            e.preventDefault();
            deletePages(Array.from(selected));
          }
        });

        /* ---------------- Build output PDF ---------------- */
        function buildPdfLib(pageList) {
          var out;
          return PDFLib.PDFDocument.create().then(function (doc) {
            out = doc;
            var chain = Promise.resolve();
            pageList.forEach(function (pg) {
              chain = chain.then(function () {
                if (pg.fileId === null) {
                  var np = out.addPage([pg.blankW, pg.blankH]);
                  if (pg.extraRot) np.setRotation(PDFLib.degrees(pg.extraRot));
                  return;
                }
                var f = files.get(pg.fileId);
                return out.copyPages(f.libDoc, [pg.pageIndex]).then(function (copied) {
                  var cp = copied[0];
                  var cur = cp.getRotation().angle;
                  cp.setRotation(PDFLib.degrees(((cur + pg.extraRot) % 360 + 360) % 360));
                  out.addPage(cp);
                });
              });
            });
            return chain;
          }).then(function () { return out.save(); });
        }

        /* Build the output with the C++ engine: per-file rotation passes,
           then one --pages run that picks the pages in the exact order. */
        function buildPdfQpdf(pageList) {
          var sources = {}; /* key -> {bytes, blank|null, rotate:{pageNo:deg}, name} */
          var order = [];   /* [{key, pageNo}] */
          pageList.forEach(function (pg) {
            if (pg.fileId === null) {
              var bk = "blank" + Math.round(pg.blankW) + "x" + Math.round(pg.blankH);
              if (!sources[bk]) sources[bk] = { blank: { w: pg.blankW, h: pg.blankH }, rotate: {} };
              if (pg.extraRot) sources[bk].rotate[1] = pg.extraRot;
              order.push({ key: bk, pageNo: 1 });
            } else {
              var fk = "f" + pg.fileId;
              if (!sources[fk]) sources[fk] = { bytes: files.get(pg.fileId).bytes, blank: null, rotate: {} };
              if (pg.extraRot) sources[fk].rotate[pg.pageIndex + 1] = pg.extraRot;
              order.push({ key: fk, pageNo: pg.pageIndex + 1 });
            }
          });
          Object.keys(sources).forEach(function (key) { sources[key].name = key + ".pdf"; });

          var prep = Promise.resolve();
          Object.keys(sources).forEach(function (key) {
            var src = sources[key];
            if (!src.blank) return;
            prep = prep.then(function () {
              return PDFLib.PDFDocument.create().then(function (doc) {
                doc.addPage([src.blank.w, src.blank.h]);
                return doc.save();
              }).then(function (bytes) { src.bytes = bytes; });
            });
          });

          return prep.then(function () {
            var chain = Promise.resolve();
            Object.keys(sources).forEach(function (key) {
              var src = sources[key];
              var rots = Object.keys(src.rotate);
              if (!rots.length) return;
              chain = chain.then(function () {
                var args = ["/" + src.name, "/out.pdf"];
                rots.forEach(function (pn) { args.push("--rotate=+" + src.rotate[pn] + ":" + pn); });
                var inputs = {}; inputs[src.name] = src.bytes;
                return runQpdf(args, inputs).then(function (bytes) { src.bytes = bytes; });
              });
            });
            return chain;
          }).then(function () {
            var args = ["--empty", "--pages"];
            var inputs = {};
            Object.keys(sources).forEach(function (key) { inputs[sources[key].name] = sources[key].bytes; });
            var i = 0;
            while (i < order.length) {
              var key = order[i].key, nums = [];
              while (i < order.length && order[i].key === key) { nums.push(order[i].pageNo); i++; }
              args.push("/" + sources[key].name, nums.join(","));
            }
            args.push("--", "/out.pdf");
            return runQpdf(args, inputs);
          });
        }

        function buildPdf(pageList) {
          if (!qpdfFactory || engineState === "fallback") return buildPdfLib(pageList);
          return engineProbe.then(function (ok) {
            if (!ok) return buildPdfLib(pageList);
            return buildPdfQpdf(pageList).then(null, function (err) {
              if (window.console) console.warn("C++-Engine fehlgeschlagen, Reserve-Engine übernimmt:", err);
              setEngine("fallback");
              return buildPdfLib(pageList);
            });
          });
        }

        function fmtSize(n) {
          return n >= 1048576
            ? (n / 1048576).toFixed(1).replace(".", ",") + " MB"
            : Math.max(1, Math.round(n / 1024)) + " KB";
        }

        /* Hand the finished PDF to the user. Plain blob-URL downloads are
           silently ignored by many phone in-app views (no download starts,
           no error shows), so the primary path on phones is the system
           share sheet: a real tap on "Datei speichern" calls
           navigator.share with the file, synchronously inside the tap, and
           the user picks "In Dateien sichern" / "Save to Files" there.
           Where file sharing is unavailable, a real tappable download link
           is primary instead (plus an automatic attempt), and "PDF öffnen"
           stays as a third path into the native viewer. The blob URL stays
           alive until the next file is built or the panel is closed. */
        var currentDlUrl = null;
        var currentFile = null;
        var currentName = "";
        function canShareFile() {
          if (!currentFile || !navigator.canShare) return false;
          try { return navigator.canShare({ files: [currentFile] }); } catch (e) { return false; }
        }
        function presentDownload(bytes, name) {
          var blob = new Blob([bytes], { type: "application/pdf" });
          if (currentDlUrl) URL.revokeObjectURL(currentDlUrl);
          currentDlUrl = URL.createObjectURL(blob);
          currentFile = null;
          try { currentFile = new File([blob], name, { type: "application/pdf" }); } catch (e) {}
          currentName = name;
          els.dlName.textContent = name;
          els.dlSave.href = currentDlUrl;
          els.dlSave.setAttribute("download", name);
          els.dlOpen.href = currentDlUrl;
          var shareOk = canShareFile();
          els.dlShare.hidden = !shareOk;
          els.dlSave.classList.toggle("primary", !shareOk);
          els.dlSub.textContent = shareOk
            ? "Tippe auf „Datei speichern“ (" + fmtSize(bytes.length) + ") und wähle dann „In Dateien sichern“ – so landet die PDF in deiner Dateien-App. Oder lade sie direkt herunter."
            : "Tippe auf „Direkt herunterladen“ – die Datei (" + fmtSize(bytes.length) + ") landet in deinem Downloads-Ordner. Klappt das nicht, tippe auf „PDF öffnen“ und speichere sie von dort.";
          els.dlpanel.hidden = false;
          if (!shareOk) { try { els.dlSave.click(); } catch (e) {} }
          toast("Fertig – speichere die PDF über die Karte unten.");
        }
        els.dlShare.addEventListener("click", function () {
          if (currentFile && navigator.share && canShareFile()) {
            navigator.share({ files: [currentFile], title: currentName }).catch(function (err) {
              if (!err || err.name !== "AbortError") { try { els.dlSave.click(); } catch (e) {} }
            });
          } else {
            try { els.dlSave.click(); } catch (e) {}
          }
        });
        els.dlClose.addEventListener("click", function () {
          els.dlpanel.hidden = true;
          currentFile = null;
          if (currentDlUrl) { URL.revokeObjectURL(currentDlUrl); currentDlUrl = null; }
        });

        function baseName() {
          if (files.size === 1) {
            var n = files.values().next().value.name.replace(/\.pdf$/i, "");
            return n + "-bearbeitet.pdf";
          }
          return "zusammengefuehrt.pdf";
        }

        els.btnDownload.addEventListener("click", function () {
          if (!pages.length) return;
          els.dlpanel.hidden = true;
          els.btnDownload.disabled = true;
          setBusy(true, "PDF wird erstellt …");
          buildPdf(pages).then(function (bytes) {
            return applyTextLayer(bytes, pages);
          }).then(function (bytes) {
            setBusy(false);
            els.btnDownload.disabled = false;
            presentDownload(bytes, baseName());
          }).catch(function () {
            setBusy(false);
            els.btnDownload.disabled = false;
            toast("Fehler beim Erstellen der PDF.", true);
          });
        });

        els.btnExtract.addEventListener("click", function () {
          var list = pages.filter(function (p) { return selected.has(p.id); });
          if (!list.length) return;
          els.dlpanel.hidden = true;
          els.btnExtract.disabled = true;
          setBusy(true, "PDF wird erstellt …");
          buildPdf(list).then(function (bytes) {
            return applyTextLayer(bytes, list);
          }).then(function (bytes) {
            setBusy(false);
            els.btnExtract.disabled = false;
            presentDownload(bytes, "auswahl.pdf");
          }).catch(function () {
            setBusy(false);
            els.btnExtract.disabled = false;
            toast("Fehler beim Erstellen der PDF.", true);
          });
        });

        /* ---------------- Rust-Engine (lopdf, WebAssembly): PDF verkleinern ----------------
           Rust laeuft ZUSAETZLICH zur C++-Engine, ersetzt sie nicht.
           Das Modul wird erst auf Knopfdruck geladen (dynamic import),
           damit die Seite schnell bleibt. Laedt Rust nicht, bleibt die
           Seite voll funktionsfaehig mit C++ (sichtbare Meldung).
           Echte Funktion (lopdf 0.35): Metadaten entfernen, ungenutzte
           Objekte entfernen, Streams neu komprimieren, neu speichern.
           Kein Passwort-Schutz: lopdf kann verschluesselte PDFs nur lesen,
           es gibt keine API zum Verschluesseln beim Speichern. */
        var rustMod = null;
        var rustLoad = null;
        var rustState = "idle";
        function setRust(state, label) {
          rustState = state;
          var dotCls = state === "ready" ? "engdot ok" : (state === "error" ? "engdot fb" : (state === "loading" ? "engdot load" : "engdot"));
          document.querySelectorAll("[data-rustdot]").forEach(function (d) { d.className = dotCls; });
          document.querySelectorAll("[data-rusttext]").forEach(function (t) { t.textContent = label; });
        }
        function loadRust() {
          if (rustMod) return Promise.resolve(rustMod);
          if (rustLoad) return rustLoad;
          setRust("loading", "Rust lädt …");
          rustLoad = import("./vendor/rust_pdf.js").then(function (m) {
            return m.default().then(function () {
              rustMod = m;
              setRust("ready", "Rust bereit (lopdf)");
              return m;
            });
          }).catch(function (err) {
            rustLoad = null;
            setRust("error", "Rust nicht verfügbar, C++ läuft weiter");
            if (window.console) console.warn("Rust-Engine konnte nicht geladen werden:", err);
            return null;
          });
          return rustLoad;
        }
        function rsNote(msg, isErr) {
          els.rsResult.textContent = msg;
          els.rsResult.className = "py-note" + (isErr ? " err" : "");
        }
        function rsSmallName() {
          var n = baseName();
          if (/-bearbeitet\.pdf$/i.test(n)) return n.replace(/-bearbeitet\.pdf$/i, "-klein.pdf");
          return n.replace(/\.pdf$/i, "-klein.pdf");
        }
        els.rsOptimize.addEventListener("click", function () {
          if (!pages.length) return;
          els.dlpanel.hidden = true;
          els.rsOptimize.disabled = true;
          setBusy(true, "Rust verkleinert die PDF …");
          buildPdf(pages).then(function (bytes) {
            return applyTextLayer(bytes, pages);
          }).then(function (bytes) {
            var before = bytes.length;
            return loadRust().then(function (m) {
              if (!m) throw new Error("rust-unavailable");
              var out = m.optimize_pdf(bytes);
              var after = out.length;
              var savedPct = (100 * (1 - after / before)).toFixed(1).replace(".", ",");
              var info = "";
              try { info = JSON.parse(m.pdf_info(out)); } catch (e) {}
              var line = "Vorher " + fmtSize(before) + " · Nachher " + fmtSize(after) +
                (after < before ? " · gespart " + savedPct + " %" : " · keine Ersparnis, die PDF war schon optimal") +
                (info && info.pages ? " · " + info.pages + " Seiten, Text und Seiten unverändert" : "");
              rsNote(line);
              setBusy(false);
              els.rsOptimize.disabled = false;
              if (after < before) {
                presentDownload(out, rsSmallName());
                toast("Rust: PDF verkleinert – " + savedPct + " % gespart.");
              } else {
                toast("Rust: Die PDF war schon optimal, keine Ersparnis.");
              }
            });
          }).catch(function (err) {
            setBusy(false);
            els.rsOptimize.disabled = false;
            if (err && err.message === "rust-unavailable") {
              rsNote("Rust konnte nicht geladen werden. Die C++-Engine läuft weiter – lade die PDF einfach oben über „PDF herunterladen“.", true);
              toast("Rust nicht verfügbar, C++ läuft weiter.", true);
            } else {
              rsNote("Fehler beim Verkleinern mit Rust.", true);
              toast("Fehler beim Verkleinern mit Rust.", true);
            }
          });
        });
        els.rsInfo.addEventListener("click", function () {
          if (!pages.length) return;
          els.rsInfo.disabled = true;
          setBusy(true, "Rust liest die PDF-Infos …");
          buildPdf(pages).then(function (bytes) {
            return applyTextLayer(bytes, pages);
          }).then(function (bytes) {
            return loadRust().then(function (m) {
              if (!m) throw new Error("rust-unavailable");
              var info = JSON.parse(m.pdf_info(bytes));
              rsNote("Rust liest: " + info.pages + " Seiten · " + info.objects + " Objekte · PDF " + info.version +
                " · verschlüsselt: " + (info.encrypted ? "ja" : "nein") + " · Größe " + fmtSize(bytes.length) + ".");
              setBusy(false);
              els.rsInfo.disabled = false;
            });
          }).catch(function (err) {
            setBusy(false);
            els.rsInfo.disabled = false;
            if (err && err.message === "rust-unavailable") {
              rsNote("Rust konnte nicht geladen werden. Die C++-Engine läuft weiter.", true);
            } else {
              rsNote("Fehler beim Lesen der PDF-Infos mit Rust.", true);
            }
          });
        });

        /* ---------------- Text & OCR: lesbar, durchsuchbar, bearbeitbar ----------------
           Zwei Wege führen zum Text einer Seite:
           1. Die PDF hat schon eine Textebene (normaler Export aus Word
              & Co.): pdf.js liest die Zeilen samt Position aus.
           2. Die Seite ist ein Scan (nur ein Bild): Die Texterkennung
              Tesseract.js (OCR, Deutsch + Englisch, läuft per WebAssembly
              im Browser) liest den Text aus dem gerenderten Seitenbild
              und liefert jede Zeile mit ihrer Position.
           In beiden Fällen steht der Text unten Zeile für Zeile in
           Eingabefeldern und kann geändert werden. Beim Speichern
           (applyTextLayer, läuft über dem fertigen PDF aus der
           C++-/Reserve-Engine) passiert dann:
           - OCR-Zeilen ohne Änderung: als unsichtbare Textebene über
             dem Scan einbetten – die PDF wird dadurch in jedem
             Programm durchsuchbar, Text lässt sich markieren/kopieren.
           - Geänderte Zeilen (egal ob Scan oder Textebene): alte Zeile
             mit einem Rechteck in der Hintergrundfarbe der Seite (aus
             dem gerenderten Seitenbild um die Zeile herum gemessen,
             nicht pauschal Weiß) überdecken und den neuen Text an der
             gleichen Stelle sichtbar einsetzen – in der Schriftart,
             Größe, Fett-/Kursiv-Form und Textfarbe der Originalzeile.
             Schriftart und Farbe liest der Editor beim Einlesen jeder
             Zeile mit aus (Schriftname aus der PDF, Farben aus dem
             Seitenbild), damit der Ersatz wie das Original aussieht
             statt wie fremder Text.
           Die OCR-Bibliothek wird erst auf Knopfdruck aus dem CDN
           geladen (Sprachdaten Deutsch + Englisch) – der Rest des
           Editors bleibt als einzelne Datei offline nutzbar. */
        var TESSERACT_SRC = "https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js";
        var tessWorker = null;
        var tessLoading = null;
        var ocrState = "idle"; /* idle | loading | ready | error */
        var ocrBusy = false;
        var pageTextData = {};     /* pg.id -> {source:'native'|'ocr'|'none', lines:[{id,text,x,y,w,fs}]} */
        var edits = {};            /* lineId -> geänderter Text */
        var nativeLinesCache = {}; /* "fileId:pageIndex" -> Zeilen ohne IDs */
        var ocrCache = {};         /* "fileId:pageIndex" -> Zeilen ohne IDs */
        var UNDO_ICON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 14 4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 5.5 5.5 5.5 5.5 0 0 1-5.5 5.5H11"/></svg>';

        function setOcr(state, label) {
          ocrState = state;
          var dotCls = state === "ready" ? "engdot ok" : (state === "error" ? "engdot fb" : (state === "loading" ? "engdot load" : "engdot"));
          document.querySelectorAll("[data-ocrdot]").forEach(function (d) { d.className = dotCls; });
          document.querySelectorAll("[data-ocrtext]").forEach(function (t) { t.textContent = label; });
        }
        function txNote(msg, isErr) {
          els.txNote.textContent = msg;
          els.txNote.className = "py-note" + (isErr ? " err" : "");
        }
        function lineKey(pg) { return pg.fileId + ":" + pg.pageIndex; }
        function withIds(pg, lines) {
          return lines.map(function (l, i) {
            return {
              id: pg.id + ":" + i, text: l.text, x: l.x, y: l.y, w: l.w, fs: l.fs,
              fontKey: l.fontKey || "Helvetica", fam: l.fam || "sans",
              bold: !!l.bold, italic: !!l.italic,
              color: l.color || null, bg: l.bg || null,
              styleLabel: l.styleLabel || ""
            };
          });
        }

        /* ---------- Original-Stil einer Zeile erkennen ----------
           Damit geänderter Text aussieht wie das Original, liest der
           Editor pro Zeile mit aus: Schriftfamilie (Serif / Sans /
           Schreibmaschine), Fett, Kursiv, genaue Größe und die Farben
           von Text und Hintergrund. Die Schrift kommt aus den Angaben
           der PDF selbst, die Farben werden aus dem gerenderten
           Seitenbild um die Zeile herum gemessen (dunkelste Pixel =
           Text, Randpixel = Hintergrund). Eingebettet werden beim
           Speichern die pdf-lib-Standardschriften, die der Original-
           schrift am nächsten kommen (Times / Helvetica / Courier in
           je vier Schnitten). */
        function classifyFont(fontName, family) {
          var s = ((fontName || "") + " " + (family || "")).toLowerCase();
          var bold = /bold|black|heavy|semibold|demibold/.test(s);
          var italic = /italic|oblique/.test(s);
          var fam = "sans";
          if (/courier|mono|consol|typewriter|ocr/.test(s)) fam = "mono";
          else if (/times|georgia|cambria|garamond|palatino|charter|book|roman/.test(s) || (/serif/.test(s) && !/sans/.test(s))) fam = "serif";
          var base = fam === "serif" ? "TimesRoman" : (fam === "mono" ? "Courier" : "Helvetica");
          var key = base;
          if (fam === "serif") key = bold && italic ? "TimesRomanBoldItalic" : bold ? "TimesRomanBold" : italic ? "TimesRomanItalic" : "TimesRoman";
          else key = bold && italic ? base + "BoldOblique" : bold ? base + "Bold" : italic ? base + "Oblique" : base;
          var cssFam = fam === "serif" ? "Georgia, 'Times New Roman', Times, serif"
            : fam === "mono" ? "'Courier New', Courier, monospace"
            : "Helvetica, Arial, sans-serif";
          var label = fam === "serif" ? "Times" : fam === "mono" ? "Courier" : "Helvetica";
          if (bold && italic) label += " fett kursiv";
          else if (bold) label += " fett";
          else if (italic) label += " kursiv";
          return { fam: fam, bold: bold, italic: italic, fontKey: key, cssFam: cssFam, label: label };
        }

        function styleForItem(it, tc, page) {
          var fam = "";
          try {
            var st = tc && tc.styles && it.fontName ? tc.styles[it.fontName] : null;
            if (st && st.fontFamily) fam = st.fontFamily;
          } catch (e) { /* Stil ist Zusatzinfo, nie ein Abbruchgrund */ }
          var realName = "";
          try {
            if (page && page.commonObjs && it.fontName) {
              var fo = page.commonObjs.get(it.fontName);
              if (fo && fo.name) realName = fo.name;
            }
          } catch (e) { /* s. o. */ }
          return classifyFont(realName + " " + (it.fontName || ""), fam);
        }

        /* Farben um eine Zeile aus dem Seitenbild messen.
           (rx, ry) ist die linke obere Ecke des Zeilenrahmens in
           Canvas-Pixeln, der Rahmen ist rw x rh groß. Hintergrund =
           Median der Randpixel, Textfarbe = Mittel der dunkelsten
           Pixel im Inneren. Liefert {bg:[r,g,b], fg:[r,g,b]} mit
           Werten 0..1 – oder null, wenn nichts Brauchbares messbar
           ist (dann gelten die bisherigen Standardfarben). */
        function sampleRegionColors(ctx, rx, ry, rw, rh) {
          try {
            rx = Math.max(0, Math.floor(rx)); ry = Math.max(0, Math.floor(ry));
            rw = Math.max(4, Math.floor(rw)); rh = Math.max(4, Math.floor(rh));
            if (rx + rw > ctx.canvas.width) rw = ctx.canvas.width - rx;
            if (ry + rh > ctx.canvas.height) rh = ctx.canvas.height - ry;
            if (rw < 4 || rh < 4) return null;
            var data = ctx.getImageData(rx, ry, rw, rh).data;
            var ringR = [], ringG = [], ringB = [], inner = [];
            for (var py = 0; py < rh; py += 1) {
              for (var px = 0; px < rw; px += 2) {
                var o = (py * rw + px) * 4;
                var r = data[o], g = data[o + 1], b = data[o + 2];
                if (px < 3 || py < 3 || px > rw - 4 || py > rh - 4) {
                  if (ringR.length < 4000) { ringR.push(r); ringG.push(g); ringB.push(b); }
                } else {
                  inner.push([r, g, b, r * 0.299 + g * 0.587 + b * 0.114]);
                }
              }
            }
            if (!ringR.length || inner.length < 8) return null;
            function med(a) { a.sort(function (x, y) { return x - y; }); return a[Math.floor(a.length / 2)]; }
            var bg = [med(ringR.slice()), med(ringG.slice()), med(ringB.slice())];
            inner.sort(function (a, b) { return a[3] - b[3]; });
            var take = Math.max(4, Math.floor(inner.length * 0.12));
            var fr = 0, fg2 = 0, fb = 0;
            for (var i = 0; i < take; i++) { fr += inner[i][0]; fg2 += inner[i][1]; fb += inner[i][2]; }
            var fg = [fr / take, fg2 / take, fb / take];
            var bgLum = bg[0] * 0.299 + bg[1] * 0.587 + bg[2] * 0.114;
            var fgLum = fg[0] * 0.299 + fg[1] * 0.587 + fg[2] * 0.114;
            if (Math.abs(bgLum - fgLum) < 28) return { bg: [bg[0] / 255, bg[1] / 255, bg[2] / 255], fg: null };
            return { bg: [bg[0] / 255, bg[1] / 255, bg[2] / 255], fg: [fg[0] / 255, fg[1] / 255, fg[2] / 255] };
          } catch (e) { return null; }
        }

        function colorCss(c) {
          if (!c) return "";
          function h(v) { var s = Math.round(Math.max(0, Math.min(1, v)) * 255).toString(16); return s.length < 2 ? "0" + s : s; }
          return "#" + h(c[0]) + h(c[1]) + h(c[2]);
        }

        /* Tintenmaß einer Zeile im Seitenbild: engster Rahmen um die
           dunklen Pixel plus die mittlere Strichstärke (Median der
           dunklen Lauflängen in der Zeilenmitte, dort stehen die
           Stämme der Buchstaben). Daraus lassen sich echte
           Schriftgröße und Fett ablesen. Das ist nötig, weil Scans in
           der PDF gar keine Schriftangaben haben und die OCR nur den
           Rahmen der ganzen Zeile liefert – mit Leerraum oben und
           unten und ganz ohne Stärke. Genau darum wirkten geänderte
           Scan-Zeilen bisher zu klein und zu dünn: Sie wurden in
           normaler Helvetica mit 74 % der Rahmenhöhe neu gesetzt,
           obwohl das Original fett und größer gedruckt war.
           (rx, ry, rw, rh) in Canvas-Pixeln, bg/fg als [r,g,b] 0..1
           (aus sampleRegionColors) für die Schwelle, sonst fest 150. */
        function measureInk(ctx, rx, ry, rw, rh, bg, fg) {
          try {
            rx = Math.max(0, Math.floor(rx)); ry = Math.max(0, Math.floor(ry));
            rw = Math.floor(rw); rh = Math.floor(rh);
            if (rx + rw > ctx.canvas.width) rw = ctx.canvas.width - rx;
            if (ry + rh > ctx.canvas.height) rh = ctx.canvas.height - ry;
            if (rw < 8 || rh < 6) return null;
            var data = ctx.getImageData(rx, ry, rw, rh).data;
            var thr = 150;
            if (bg && fg) {
              var bl = (bg[0] * 0.299 + bg[1] * 0.587 + bg[2] * 0.114) * 255;
              var fl = (fg[0] * 0.299 + fg[1] * 0.587 + fg[2] * 0.114) * 255;
              if (bl - fl > 28) thr = (bl + fl) / 2;
            }
            function isDark(o) { return data[o] * 0.299 + data[o + 1] * 0.587 + data[o + 2] * 0.114 < thr; }
            var rows = [], cols = [], darkTotal = 0, py, px;
            for (py = 0; py < rh; py++) rows.push(0);
            for (px = 0; px < rw; px++) cols.push(0);
            for (py = 0; py < rh; py++) {
              for (px = 0; px < rw; px++) {
                if (isDark((py * rw + px) * 4)) { rows[py]++; cols[px]++; darkTotal++; }
              }
            }
            if (darkTotal < 12) return null;
            var top = -1, bottom = -1, left = -1, right = -1, k;
            for (k = 0; k < rh; k++) { if (rows[k] >= 2) { top = k; break; } }
            for (k = rh - 1; k >= 0; k--) { if (rows[k] >= 2) { bottom = k; break; } }
            for (k = 0; k < rw; k++) { if (cols[k] >= 2) { left = k; break; } }
            for (k = rw - 1; k >= 0; k--) { if (cols[k] >= 2) { right = k; break; } }
            if (top < 0 || bottom <= top || left < 0 || right <= left) return null;
            var inkH = bottom - top + 1;
            var bandTop = top + Math.floor(inkH * 0.28);
            var bandBot = top + Math.ceil(inkH * 0.72);
            var runs = [];
            for (var by = bandTop; by <= bandBot && by < rh; by++) {
              var run = 0;
              for (var bx = left; bx <= right; bx++) {
                if (isDark((by * rw + bx) * 4)) { run++; }
                else if (run > 0) { runs.push(run); run = 0; }
              }
              if (run > 0) runs.push(run);
            }
            if (!runs.length) return null;
            runs.sort(function (a, b) { return a - b; });
            return { top: top, bottom: bottom, left: left, right: right, medianRun: runs[Math.floor(runs.length / 2)] };
          } catch (e) { return null; }
        }

        /* Aus dem Tintenmaß Größe und Fett einer Zeile schätzen: Die
           Tintenhöhe reicht von der Oberlänge (Großbuchstaben,
           Ziffern, b/d/f/h/k/l/t ≈ 0,72 der Schriftgröße; reine
           Kleinbuchstaben nur Mittellänge ≈ 0,52) bis zur Unterlänge,
           wenn die Zeile Unterlängen enthält (g, j, p, q, y ≈ 0,21).
           Fett erkennt man an der Strichstärke im Verhältnis zur
           Größe: normal ≈ 0,08–0,11, fett ≈ 0,15–0,20. */
        function inkTextStyle(ink, text, scale) {
          var inkHpt = (ink.bottom - ink.top + 1) / scale;
          var hasTall = /[A-ZÄÖÜ0-9bdfhkl(\/]/.test(text || "");
          var hasDesc = /[gjpqyQJ,;]/.test(text || "");
          var extent = (hasTall ? 0.72 : 0.52) + (hasDesc ? 0.21 : 0);
          var fs = Math.round((inkHpt / extent) * 10) / 10;
          if (!isFinite(fs) || fs <= 0) return null;
          fs = Math.max(5, Math.min(60, fs));
          var bold = (ink.medianRun / (fs * scale)) >= 0.14;
          return { fs: fs, bold: bold, hasDesc: hasDesc };
        }

        function boldFontKey(key) {
          if (!key) return "HelveticaBold";
          if (/Bold/.test(key)) return key;
          if (/Oblique$/.test(key)) return key.replace(/Oblique$/, "BoldOblique");
          if (/Italic$/.test(key)) return key.replace(/Italic$/, "BoldItalic");
          return key + "Bold";
        }

        /* pdf-lib schreibt mit Standardschriften (WinAnsi-Zeichensatz).
           Zeichen außerhalb dieses Zeichensatzes würden beim Speichern
           einen Fehler werfen – sie werden hier vorher ersetzt/entfernt,
           damit eine einzige exotische Zeile nie den Export killt. */
        var WINANSI_EXTRA_CHARS = "€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ";
        function sanitizeForPdf(text) {
          var out = "";
          for (var i = 0; i < text.length; i++) {
            var code = text.charCodeAt(i);
            var ch = text.charAt(i);
            if (code === 0xA0 || code === 0x202F || code === 0x09) { out += " "; continue; }
            if (code >= 0x20 && code <= 0x7E) { out += ch; continue; }
            if (code >= 0xA0 && code <= 0xFF && code !== 0x81 && code !== 0x8D && code !== 0x8F && code !== 0x90 && code !== 0x9D) { out += ch; continue; }
            if (WINANSI_EXTRA_CHARS.indexOf(ch) !== -1) { out += ch; continue; }
          }
          return out;
        }

        var measureCtx = document.createElement("canvas").getContext("2d");
        function measurePx(text, fontPx, style) {
          try {
            var fam = style && style.cssFam ? style.cssFam : "Helvetica, Arial, sans-serif";
            measureCtx.font = (style && style.italic ? "italic " : "") + (style && style.bold ? "700 " : "400 ") + fontPx + "px " + fam;
            return measureCtx.measureText(text).width;
          } catch (e) { return 0; }
        }

        /* Zeilen einer vorhandenen Textebene lesen: pdf.js liefert die
           Textstücke mit Position (Transformationsmatrix). Stücke mit
           fast gleicher Grundlinie werden zu einer Zeile verbunden,
           alle Positionen über den Viewport in echte PDF-Punkte
           (Ursprung unten links) umgerechnet – genau das Koordinaten-
           system, in dem pdf-lib später malt. */
        function extractNativeLines(pg) {
          if (pg.fileId === null) return Promise.resolve([]);
          var key = lineKey(pg);
          if (nativeLinesCache[key]) return Promise.resolve(nativeLinesCache[key]);
          var f = files.get(pg.fileId);
          if (!f || !f.jsDocPromise) { nativeLinesCache[key] = []; return Promise.resolve([]); }
          return f.jsDocPromise.then(function (jsDoc) {
            return jsDoc.getPage(pg.pageIndex + 1);
          }).then(function (page) {
            var viewport = page.getViewport({ scale: 2 });
            return page.getTextContent().then(function (tc) {
              var raw = [];
              (tc.items || []).forEach(function (it) {
                if (!it.str || !it.str.trim()) return;
                var tx = pdfjsLib.Util.transform(viewport.transform, it.transform);
                var fontPx = Math.sqrt(tx[2] * tx[2] + tx[3] * tx[3]);
                if (!isFinite(fontPx) || fontPx <= 0) fontPx = 12 * viewport.scale;
                raw.push({
                  str: it.str, x: tx[4], yBase: tx[5],
                  w: Math.max(0, (it.width || 0) * viewport.scale),
                  fontPx: fontPx, style: styleForItem(it, tc, page)
                });
              });
              var groups = [];
              raw.forEach(function (r) {
                var g = null;
                for (var i = groups.length - 1; i >= 0; i--) {
                  if (Math.abs(groups[i].yBase - r.yBase) <= Math.max(3, r.fontPx * 0.45)) { g = groups[i]; break; }
                }
                if (!g) { g = { yBase: r.yBase, fontPx: r.fontPx, items: [], style: r.style, bestLen: -1 }; groups.push(g); }
                g.items.push(r);
                /* Maßgeblich für Schrift und Größe der Zeile ist das
                   längste Stück – nicht das größte Einzelzeichen.
                   Früher zählte das Maximum, dadurch bekamen Zeilen mit
                   einer einzelnen großen Zahl eine falsche Größe und
                   wirkten nach dem Ändern fremd. */
                var ln = r.str.trim().length;
                if (ln > g.bestLen) { g.bestLen = ln; g.style = r.style; g.fontPx = r.fontPx; }
              });
              groups.sort(function (a, b) { return a.yBase - b.yBase; });
              var lines = [], metas = [];
              groups.forEach(function (g) {
                g.items.sort(function (a, b) { return a.x - b.x; });
                var text = "", x0 = Infinity, x1 = -Infinity, prevEnd = null;
                g.items.forEach(function (r) {
                  if (prevEnd !== null && r.x - prevEnd > g.fontPx * 0.22 && text && !/\s$/.test(text) && !/^\s/.test(r.str)) text += " ";
                  text += r.str;
                  x0 = Math.min(x0, r.x);
                  x1 = Math.max(x1, r.x + Math.max(r.w, measurePx(r.str, r.fontPx, r.style)));
                  prevEnd = r.x + r.w;
                });
                text = text.replace(/\s+/g, " ").trim();
                if (!text) return;
                var pt = viewport.convertToPdfPoint(x0, g.yBase);
                var fsPt = Math.round((g.fontPx / viewport.scale) * 10) / 10;
                lines.push({
                  text: text, x: pt[0], y: pt[1], w: (x1 - x0) / viewport.scale, fs: fsPt,
                  fontKey: g.style.fontKey, fam: g.style.fam, bold: g.style.bold, italic: g.style.italic,
                  styleLabel: g.style.label + " · " + ("" + fsPt).replace(".", ",") + " pt"
                });
                metas.push({ x0: x0, x1: x1, yBase: g.yBase, fontPx: g.fontPx });
              });
              if (!lines.length) { nativeLinesCache[key] = lines; return lines; }
              /* Farben aus dem Seitenbild messen: Seite einmal in
                 genau diesem Viewport rendern und pro Zeile Text- und
                 Hintergrundfarbe bestimmen. Schlägt das Rendern fehl,
                 bleiben die Zeilen ohne Farben – beim Speichern gelten
                 dann die Standardwerte. */
              var canvas = document.createElement("canvas");
              canvas.width = Math.floor(viewport.width);
              canvas.height = Math.floor(viewport.height);
              var ctx = canvas.getContext("2d");
              ctx.fillStyle = "#ffffff";
              ctx.fillRect(0, 0, canvas.width, canvas.height);
              return page.render({ canvasContext: ctx, viewport: viewport }).promise.then(function () {
                lines.forEach(function (line, i) {
                  var m = metas[i];
                  var c = sampleRegionColors(ctx, m.x0 - m.fontPx * 0.18, m.yBase - m.fontPx * 1.02, (m.x1 - m.x0) + m.fontPx * 0.36, m.fontPx * 1.5);
                  if (c) { line.bg = c.bg; if (c.fg) line.color = c.fg; }
                  /* Gegenprobe im Bild: Manche PDFs (z. B. Scans mit
                     unsichtbarer Textebene vom Scanner) nennen für
                     eine sichtbar fette, große Zeile eine neutrale
                     Schrift in falscher Größe. Dann zählt das Bild:
                     Strichstärke und Tintenhöhe korrigieren Fett und
                     Größe, sonst wirkt geänderter Text dünner und
                     kleiner als das Original. Bei echten Text-PDFs
                     stimmen Maß und Angabe überein – es ändert sich
                     nichts (Korrektur erst ab 18 % Abweichung). */
                  var ink = measureInk(ctx, m.x0 - m.fontPx * 0.18, m.yBase - m.fontPx * 1.02, (m.x1 - m.x0) + m.fontPx * 0.36, m.fontPx * 1.5, c && c.bg, c && c.fg);
                  if (ink) {
                    var ist = inkTextStyle(ink, line.text, viewport.scale);
                    if (ist) {
                      if (!line.bold && ist.bold) {
                        line.bold = true;
                        line.fontKey = boldFontKey(line.fontKey);
                        line.styleLabel = line.styleLabel.replace(/ · /, " fett · ");
                      }
                      if (line.fs > 0 && Math.abs(ist.fs - line.fs) / line.fs > 0.18) {
                        line.fs = ist.fs;
                        line.styleLabel = line.styleLabel.replace(/[0-9]+(?:[.,][0-9])? pt$/, ("" + ist.fs).replace(".", ",") + " pt");
                      }
                    }
                  }
                });
                nativeLinesCache[key] = lines;
                return lines;
              }).catch(function () {
                nativeLinesCache[key] = lines;
                return lines;
              });
            });
          }).catch(function () { nativeLinesCache[key] = []; return []; });
        }

        /* OCR einer Seite: Seite groß rendern (ca. 2300 px breit, gut
           für die Erkennung), Tesseract liest Zeilen samt Rahmen aus
           dem Bild, Rahmen werden in PDF-Punkte umgerechnet. */
        function ensureTesseract() {
          if (tessWorker) return Promise.resolve(tessWorker);
          if (tessLoading) return tessLoading;
          setOcr("loading", "OCR lädt …");
          tessLoading = new Promise(function (resolve, reject) {
            function have() { return typeof window.Tesseract !== "undefined" && !!window.Tesseract.createWorker; }
            if (have()) { resolve(); return; }
            var s = document.createElement("script");
            s.src = TESSERACT_SRC;
            s.onload = function () { if (have()) resolve(); else reject(new Error("Tesseract leer")); };
            s.onerror = function () { reject(new Error("tesseract.min.js nicht erreichbar")); };
            document.head.appendChild(s);
          }).then(function () {
            return window.Tesseract.createWorker(["deu", "eng"]);
          }).then(function (w) {
            tessWorker = w;
            setOcr("ready", "OCR bereit (Deutsch + Englisch)");
            return w;
          }).catch(function (err) {
            tessLoading = null;
            setOcr("error", "OCR nicht geladen");
            throw err;
          });
          return tessLoading;
        }

        function ocrPage(pg) {
          var key = lineKey(pg);
          if (ocrCache[key]) return Promise.resolve(ocrCache[key]);
          var f = files.get(pg.fileId);
          if (!f || !f.jsDocPromise) { ocrCache[key] = []; return Promise.resolve([]); }
          return f.jsDocPromise.then(function (jsDoc) {
            return jsDoc.getPage(pg.pageIndex + 1);
          }).then(function (page) {
            var base = page.getViewport({ scale: 1 });
            var scale = Math.min(3.2, Math.max(1.6, 2300 / base.width));
            var viewport = page.getViewport({ scale: scale });
            var canvas = document.createElement("canvas");
            canvas.width = Math.floor(viewport.width);
            canvas.height = Math.floor(viewport.height);
            var ctx = canvas.getContext("2d");
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            return page.render({ canvasContext: ctx, viewport: viewport }).promise.then(function () {
              return ensureTesseract().then(function (worker) {
                return worker.recognize(canvas, {}, { blocks: true });
              }).then(function (result) {
                var lines = [];
                var blocks = (result && result.data && result.data.blocks) || [];
                blocks.forEach(function (b) {
                  (b.paragraphs || []).forEach(function (par) {
                    (par.lines || []).forEach(function (ln) {
                      var text = (ln.text || "").replace(/\s+/g, " ").trim();
                      if (!text || !ln.bbox) return;
                      var tl = viewport.convertToPdfPoint(ln.bbox.x0, ln.bbox.y0);
                      var br = viewport.convertToPdfPoint(ln.bbox.x1, ln.bbox.y1);
                      var x = Math.min(tl[0], br[0]);
                      var w = Math.abs(br[0] - tl[0]);
                      var top = Math.max(tl[1], br[1]);
                      var bottom = Math.min(tl[1], br[1]);
                      var h = Math.max(4, top - bottom);
                      var fsOcr = Math.max(5, Math.round(h * 0.74 * 10) / 10);
                      /* Papier- und Schriftfarbe der Scan-Zeile aus dem
                         Bild messen: Wird die Zeile später geändert,
                         überdeckt der Editor sie im gleichen Papierton
                         statt mit einem weißen Fleck und schreibt im
                         gleichen Farbton wie die Scan-Schrift. */
                      var oc = sampleRegionColors(ctx, ln.bbox.x0 - 3, ln.bbox.y0 - 3, (ln.bbox.x1 - ln.bbox.x0) + 6, (ln.bbox.y1 - ln.bbox.y0) + 6);
                      var ocrLine = {
                        text: text, x: x, y: bottom + h * 0.16, w: w, fs: fsOcr,
                        fontKey: "Helvetica", fam: "sans", bold: false, italic: false,
                        styleLabel: "Scan · " + ("" + fsOcr).replace(".", ",") + " pt"
                      };
                      if (oc) { ocrLine.bg = oc.bg; if (oc.fg) ocrLine.color = oc.fg; }
                      /* Echte Größe, Fett und Grundlinie aus dem Bild
                         messen (Tinte statt OCR-Rahmen): Der Rahmen
                         der OCR enthält Leerraum und keine Stärke –
                         mit ihm wurde eine fette, große Zeile wie
                         „Kleyerstraße 92b" dünn und klein neu gesetzt.
                         Gemessen wird jetzt: Tintenhöhe → Größe,
                         Strichstärke → fett, Tintenrand → Position. */
                      var ink = measureInk(ctx, ln.bbox.x0 - 3, ln.bbox.y0 - 3, (ln.bbox.x1 - ln.bbox.x0) + 6, (ln.bbox.y1 - ln.bbox.y0) + 6, oc && oc.bg, oc && oc.fg);
                      if (ink) {
                        var ist = inkTextStyle(ink, text, scale);
                        if (ist) {
                          ocrLine.fs = ist.fs;
                          if (ist.bold) { ocrLine.bold = true; ocrLine.fontKey = "HelveticaBold"; }
                          var inkTl = viewport.convertToPdfPoint(ln.bbox.x0 - 3 + ink.left, ln.bbox.y0 - 3 + ink.top);
                          var inkBr = viewport.convertToPdfPoint(ln.bbox.x0 - 3 + ink.right + 1, ln.bbox.y0 - 3 + ink.bottom + 1);
                          ocrLine.x = Math.min(inkTl[0], inkBr[0]);
                          ocrLine.w = Math.abs(inkBr[0] - inkTl[0]);
                          ocrLine.y = Math.min(inkTl[1], inkBr[1]) + (ist.hasDesc ? ist.fs * 0.21 : 0);
                          ocrLine.styleLabel = "Scan · Helvetica" + (ist.bold ? " fett" : "") + " · " + ("" + ist.fs).replace(".", ",") + " pt";
                        }
                      }
                      lines.push(ocrLine);
                    });
                  });
                });
                ocrCache[key] = lines;
                return lines;
              });
            });
          }).catch(function (err) {
            if (window.console) console.warn("OCR-Seite fehlgeschlagen:", err);
            ocrCache[key] = [];
            return [];
          });
        }

        function ensurePageData(pg) {
          if (pageTextData[pg.id]) return Promise.resolve(pageTextData[pg.id]);
          if (pg.fileId === null) {
            pageTextData[pg.id] = { source: "none", lines: [] };
            return Promise.resolve(pageTextData[pg.id]);
          }
          var key = lineKey(pg);
          if (ocrCache[key] && ocrCache[key].length) {
            pageTextData[pg.id] = { source: "ocr", lines: withIds(pg, ocrCache[key]) };
            return Promise.resolve(pageTextData[pg.id]);
          }
          return extractNativeLines(pg).then(function (lines) {
            var hasText = lines.some(function (l) { return l.text.trim().length >= 2; });
            pageTextData[pg.id] = { source: hasText ? "native" : "none", lines: withIds(pg, lines) };
            return pageTextData[pg.id];
          });
        }

        function loadAllPageData() {
          var chain = Promise.resolve();
          pages.forEach(function (pg) {
            chain = chain.then(function () { return ensurePageData(pg); });
          });
          return chain.then(function () { renderTxPages(); });
        }

        function pageLabel(idx) {
          var pg = pages[idx];
          if (pg.fileId === null) return "Leere Seite";
          var f = files.get(pg.fileId);
          return (f ? f.name : "") + " · Seite " + (pg.pageIndex + 1);
        }

        function renderTxPages() {
          if (!els.txPages) return;
          els.txPages.innerHTML = "";
          var anyText = false;
          pages.forEach(function (pg, idx) {
            var data = pageTextData[pg.id];
            var box = document.createElement("div");
            box.className = "tx-page";
            var head = document.createElement("div");
            head.className = "tx-pagehead";
            var t = document.createElement("span");
            t.className = "t"; t.textContent = "Seite " + (idx + 1);
            head.appendChild(t);
            var sub = document.createElement("span");
            sub.className = "sub"; sub.textContent = pageLabel(idx);
            head.appendChild(sub);
            var badge = document.createElement("span");
            if (!data) { badge.className = "tx-src none"; badge.textContent = "Text wird gelesen …"; }
            else if (data.source === "ocr") { badge.className = "tx-src ocr"; badge.textContent = "OCR-Text erkannt"; }
            else if (data.source === "native") { badge.className = "tx-src"; badge.textContent = "Text vorhanden"; }
            else { badge.className = "tx-src none"; badge.textContent = "Kein Text – Scan?"; }
            head.appendChild(badge);
            box.appendChild(head);
            if (data && data.lines.length) {
              anyText = true;
              var wrap = document.createElement("div");
              wrap.className = "tx-lines";
              data.lines.forEach(function (line) {
                var isChanged = edits[line.id] !== undefined && edits[line.id] !== line.text;
                var row = document.createElement("div");
                row.className = "tx-line";
                var input = document.createElement("input");
                input.type = "text";
                input.value = edits[line.id] !== undefined ? edits[line.id] : line.text;
                input.setAttribute("aria-label", "Textzeile auf Seite " + (idx + 1));
                if (isChanged) input.classList.add("changed");
                /* Das Feld zeigt die Zeile schon in der Schrift des
                   Originals (Familie, Fett, Kursiv, Farbe), damit man
                   vor dem Speichern sieht, wie der Ersatz aussehen
                   wird. */
                input.style.fontFamily = line.fam === "serif" ? "Georgia, 'Times New Roman', Times, serif"
                  : line.fam === "mono" ? "'Courier New', Courier, monospace"
                  : "Helvetica, Arial, sans-serif";
                if (line.bold) input.style.fontWeight = "700";
                if (line.italic) input.style.fontStyle = "italic";
                if (line.color) input.style.color = colorCss(line.color);
                var undo = document.createElement("button");
                undo.type = "button";
                undo.className = "tx-undo";
                undo.title = "Änderung zurücknehmen";
                undo.setAttribute("aria-label", "Änderung an dieser Zeile zurücknehmen");
                undo.innerHTML = UNDO_ICON;
                undo.hidden = !isChanged;
                input.addEventListener("input", function () {
                  if (input.value === line.text) {
                    delete edits[line.id];
                    input.classList.remove("changed");
                    undo.hidden = true;
                  } else {
                    edits[line.id] = input.value;
                    input.classList.add("changed");
                    undo.hidden = false;
                  }
                });
                undo.addEventListener("click", function () {
                  delete edits[line.id];
                  input.value = line.text;
                  input.classList.remove("changed");
                  undo.hidden = true;
                });
                var chip = document.createElement("span");
                chip.className = "tx-style";
                chip.title = "Diese Schrift übernimmt der neue Text: " + (line.styleLabel || "Helvetica")
                  + (line.color ? ", Textfarbe " + colorCss(line.color) : "");
                var dot = document.createElement("span");
                dot.className = "tx-dot";
                dot.style.background = line.color ? colorCss(line.color) : "#17191d";
                chip.appendChild(dot);
                var chipName = document.createElement("span");
                chipName.className = "tx-style-name";
                chipName.textContent = line.styleLabel || "";
                chip.appendChild(chipName);
                row.appendChild(input);
                row.appendChild(chip);
                row.appendChild(undo);
                wrap.appendChild(row);
              });
              box.appendChild(wrap);
            } else if (data) {
              var p = document.createElement("p");
              p.className = "tx-nolines";
              p.textContent = pg.fileId === null
                ? "Leere Seite – hier gibt es keinen Text."
                : "Diese Seite hat keine Textebene. Wenn es ein Scan ist: oben auf „Texterkennung (OCR) starten“ tippen – dann erscheint der erkannte Text hier und die Seite wird durchsuchbar.";
              box.appendChild(p);
            }
            els.txPages.appendChild(box);
          });
          els.txDownloadTxt.disabled = !anyText;
        }

        function runOcr() {
          if (!pages.length) { toast("Bitte zuerst eine PDF laden.", true); return; }
          if (ocrBusy) return;
          ocrBusy = true;
          els.txOcr.disabled = true;
          els.txProgress.hidden = false;
          els.txProgressText.textContent = "Seiten werden geprüft …";
          loadAllPageData().then(function () {
            var targets = pages.filter(function (pg) {
              if (pg.fileId === null) return false;
              var d = pageTextData[pg.id];
              return d && d.source !== "native";
            });
            if (!targets.length) {
              txNote("Alle Seiten haben schon eine Textebene – Texterkennung ist nicht nötig. Du kannst unten direkt Text ändern, oben im Suchfeld suchen und dann speichern.");
              return null;
            }
            return ensureTesseract().then(function () {
              var chain = Promise.resolve();
              var done = 0, found = 0;
              targets.forEach(function (pg) {
                chain = chain.then(function () {
                  els.txProgressText.textContent = "Texterkennung läuft: Seite " + (pages.indexOf(pg) + 1) + " von " + pages.length + " (Scan " + (done + 1) + " von " + targets.length + ") …";
                  return ocrPage(pg).then(function (lines) {
                    done++;
                    if (lines.length) {
                      found++;
                      pageTextData[pg.id] = { source: "ocr", lines: withIds(pg, lines) };
                    }
                    renderTxPages();
                  });
                });
              });
              return chain.then(function () {
                if (found) {
                  txNote("Fertig: Auf " + found + " von " + targets.length + " Seiten ohne Text wurde Text erkannt. Er steht unten Zeile für Zeile – du kannst ihn noch ändern. Beim Speichern („PDF herunterladen“) landet er als Textebene in der PDF: danach ist sie durchsuchbar und der Text lässt sich kopieren.");
                  toast("Texterkennung fertig – " + found + " Seite(n) erkannt.");
                } else {
                  txNote("Die Texterkennung ist durchgelaufen, hat aber keinen Text gefunden. Sind die Seiten vielleicht verdreht oder sehr blass? Drehe sie oben im Raster richtig herum und versuche es noch einmal.", true);
                  toast("Kein Text erkannt.", true);
                }
              });
            });
          }).catch(function (err) {
            if (window.console) console.warn("OCR-Fehler:", err);
            txNote("Die Texterkennung konnte nicht starten. Beim ersten Start lädt sie die OCR mit Sprachdaten (Deutsch + Englisch) aus dem Internet – prüfe die Verbindung und tippe es noch einmal an.", true);
            toast("Texterkennung konnte nicht laden.", true);
          }).then(function () {
            ocrBusy = false;
            els.txOcr.disabled = false;
            els.txProgress.hidden = true;
          });
        }
        els.txOcr.addEventListener("click", runOcr);

        function runTxSearch() {
          var qRaw = els.txSearch.value.trim();
          var q = qRaw.toLowerCase();
          if (!q) { els.txSearchBlock.hidden = true; return; }
          if (!pages.length) { toast("Bitte zuerst eine PDF laden.", true); return; }
          loadAllPageData().then(function () {
            els.txSearchResults.innerHTML = "";
            var total = 0, hitPages = [];
            pages.forEach(function (pg, idx) {
              var d = pageTextData[pg.id];
              if (!d) return;
              var hits = 0, sample = null;
              d.lines.forEach(function (line) {
                var finalText = edits[line.id] !== undefined ? edits[line.id] : line.text;
                var hay = finalText.toLowerCase(), pos = 0, c = 0;
                while ((pos = hay.indexOf(q, pos)) !== -1) { c++; pos += q.length; }
                if (c) { hits += c; if (!sample) sample = finalText; }
              });
              if (hits) { total += hits; hitPages.push({ idx: idx, hits: hits, sample: sample }); }
            });
            els.txSearchBlock.hidden = false;
            var head = document.createElement("p");
            head.style.cssText = "margin:0 0 4px;font-size:14px;color:var(--ink-2)";
            head.appendChild(document.createTextNode("„" + qRaw + "“ kommt "));
            var hb = document.createElement("b");
            hb.style.color = "var(--ink)";
            hb.textContent = total + " Mal";
            head.appendChild(hb);
            head.appendChild(document.createTextNode(" vor:"));
            els.txSearchResults.appendChild(head);
            if (!hitPages.length) {
              var none = document.createElement("p");
              none.style.cssText = "margin:0;font-size:14px;color:var(--ink-2)";
              none.textContent = "Auf keiner Seite gefunden. Groß- und Kleinschreibung ist egal. Bei einer gescannten PDF zuerst die Texterkennung (OCR) laufen lassen, sonst ist der Text nur ein Bild.";
              els.txSearchResults.appendChild(none);
            } else {
              var ul = document.createElement("ul");
              ul.className = "py-hitlist";
              hitPages.forEach(function (hp) {
                var li = document.createElement("li");
                var b = document.createElement("b");
                b.textContent = "Seite " + (hp.idx + 1);
                li.appendChild(b);
                li.appendChild(document.createTextNode(" (" + pageLabel(hp.idx) + "): " + hp.hits + (hp.hits === 1 ? " Treffer" : " Treffer") + " – „" + (hp.sample.length > 60 ? hp.sample.slice(0, 60) + "…" : hp.sample) + "“"));
                ul.appendChild(li);
              });
              els.txSearchResults.appendChild(ul);
            }
          });
        }
        els.txSearchBtn.addEventListener("click", runTxSearch);
        els.txSearch.addEventListener("keydown", function (e) {
          if (e.key === "Enter") { e.preventDefault(); runTxSearch(); }
        });

        els.txDownloadTxt.addEventListener("click", function () {
          var out = [];
          pages.forEach(function (pg, idx) {
            out.push("===== Seite " + (idx + 1) + " (" + pageLabel(idx) + ") =====");
            var d = pageTextData[pg.id];
            if (d && d.lines.length) {
              d.lines.forEach(function (line) {
                out.push(edits[line.id] !== undefined ? edits[line.id] : line.text);
              });
            } else {
              out.push("(kein Text – Scan ohne Texterkennung?)");
            }
            out.push("");
          });
          var blob = new Blob([out.join("\n")], { type: "text/plain;charset=utf-8" });
          var url = URL.createObjectURL(blob);
          var a = document.createElement("a");
          a.href = url;
          a.download = baseName().replace(/\.pdf$/i, "") + "-text.txt";
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(function () { URL.revokeObjectURL(url); }, 4000);
          toast("Textdatei wird heruntergeladen.");
        });

        els.btnTxJump.addEventListener("click", function () {
          showView("ocr");
        });

        /* ---- Start-Auswahl: nur eine Funktion zur Zeit ----
           currentView: "home" | "pages" | "ocr" | "rust". Der Wechsel
           blendet nur Bereiche ein/aus – die geladenen Dateien und
           Seiten (files, pages) bleiben im Speicher und gehen beim
           Wechsel nicht verloren. OCR und Rust laden weiter erst auf
           Knopfdruck in ihrer eigenen Funktion. */
        var currentView = "home";
        var VIEW_TITLES = { pages: "Seiten bearbeiten", ocr: "Text & OCR", rust: "PDF verkleinern (Rust)" };
        function applyView() {
          var has = pages.length > 0 || files.size > 0;
          document.body.dataset.view = currentView;
          els.homeView.hidden = currentView !== "home";
          els.viewbar.hidden = currentView === "home";
          els.viewTitle.textContent = VIEW_TITLES[currentView] || "";
          els.empty.hidden = !(currentView === "pages" && !has);
          els.grid.hidden = !(currentView === "pages" && has);
          els.txPanel.hidden = currentView !== "ocr";
          els.rsPanel.hidden = currentView !== "rust";
          els.statusbar.hidden = !(currentView !== "home" && has);
          if (has) {
            els.homeLoaded.hidden = false;
            els.homeLoaded.textContent = "Geladen: " + files.size + (files.size === 1 ? " Datei, " : " Dateien, ") + pages.length + (pages.length === 1 ? " Seite" : " Seiten") + " – bleibt beim Wechsel erhalten.";
          } else {
            els.homeLoaded.hidden = true;
          }
          if (currentView === "home") els.dlpanel.hidden = true;
        }
        function showView(view) {
          currentView = view;
          applyView();
          if (view === "ocr" && pages.length) loadAllPageData();
          window.scrollTo(0, 0);
        }
        document.querySelectorAll("[data-goto]").forEach(function (btn) {
          btn.addEventListener("click", function () { showView(btn.getAttribute("data-goto")); });
        });
        els.btnHome.addEventListener("click", function () { showView("home"); });
        els.btnOther.addEventListener("click", function () { showView("home"); });
        /* Das Label "PDF hinzufügen" in der Funktions-Leiste ist ein
           <label for="fileInput"> und öffnet die Auswahl nativ; für
           die Tastatur zusätzlich per Enter/Leertaste. */
        document.getElementById("btnAddInView").addEventListener("keydown", function (e) {
          if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openPicker(); }
        });

        /* Textebene + Textänderungen in die fertige PDF einarbeiten.
           Läuft als pdf-lib-Nachbearbeitung über dem Ergebnis der
           C++-/Reserve-Engine – die Seitenreihenfolge ist 1:1 die von
           pageList. Schlägt die Nachbearbeitung fehl, wird das
           unveränderte PDF ausgeliefert statt gar keins. */
        function pageHasTextWork(pg) {
          var d = pageTextData[pg.id];
          if (!d || !d.lines.length) return false;
          if (d.source === "ocr") return true;
          return d.lines.some(function (line) {
            return edits[line.id] !== undefined && edits[line.id] !== line.text;
          });
        }

        function applyTextLayer(bytes, pageList) {
          if (!pageList.some(pageHasTextWork)) return Promise.resolve(bytes);
          return PDFLib.PDFDocument.load(bytes.slice(0)).then(function (doc) {
            /* Alle Schriften einbetten, die die geänderten Zeilen
               brauchen – je Zeile die Standardschrift, die ihrem
               Original am nächsten kommt (früher wurde alles in
               Helvetica und Schwarz gesetzt, darum sah geänderter
               Text fremd aus). */
            var needed = { Helvetica: true };
            pageList.forEach(function (pg) {
              var d = pageTextData[pg.id];
              if (!d || !d.lines.length) return;
              d.lines.forEach(function (line) {
                if (edits[line.id] !== undefined && edits[line.id] !== line.text) {
                  needed[line.fontKey || "Helvetica"] = true;
                }
              });
            });
            var fonts = {};
            var chain = Promise.resolve();
            Object.keys(needed).forEach(function (k) {
              chain = chain.then(function () {
                return doc.embedFont(PDFLib.StandardFonts[k] || PDFLib.StandardFonts.Helvetica).then(function (f) { fonts[k] = f; });
              });
            });
            return chain.then(function () {
              var white = PDFLib.rgb(1, 1, 1);
              var black = PDFLib.rgb(0.08, 0.08, 0.08);
              function rgbOf(c, fallback) {
                return c && c.length === 3 ? PDFLib.rgb(c[0], c[1], c[2]) : fallback;
              }
              pageList.forEach(function (pg, i) {
                var d = pageTextData[pg.id];
                if (!d || !d.lines.length) return;
                var page = doc.getPage(i);
                d.lines.forEach(function (line) {
                  var changed = edits[line.id] !== undefined && edits[line.id] !== line.text;
                  var finalText = changed ? edits[line.id] : line.text;
                  try {
                    if (d.source === "ocr" && !changed) {
                      /* Unsichtbare Textebene über dem Scan: macht die
                         Seite durchsuchbar, ohne das Bild zu verändern. */
                      if (finalText && finalText.trim()) {
                        page.drawText(sanitizeForPdf(finalText), {
                          x: line.x, y: line.y, size: Math.max(4, line.fs),
                          font: fonts.Helvetica, opacity: 0
                        });
                      }
                    } else if (changed) {
                      /* Alte Zeile in der gemessenen Hintergrundfarbe
                         der Seite überdecken (Papierton des Scans bzw.
                         Farbe hinter dem Text – kein weißer Fleck) und
                         den neuen Text in Schrift, Größe und Farbe des
                         Originals an dieselbe Stelle setzen.
                         Leer = Zeile löschen. Das Rechteck deckt die
                         volle Zeilenhöhe ab (Ober- und Unterlängen),
                         damit keine Reste der alten Zeichen bleiben. */
                      page.drawRectangle({
                        x: line.x - line.fs * 0.14, y: line.y - line.fs * 0.34,
                        width: line.w + line.fs * 0.28, height: line.fs * 1.5,
                        color: rgbOf(line.bg, white)
                      });
                      if (finalText && finalText.trim()) {
                        var fnt = fonts[line.fontKey || "Helvetica"] || fonts.Helvetica;
                        var txt = sanitizeForPdf(finalText);
                        var size = Math.max(4, line.fs);
                        /* Nur wenn der neue Text sonst über den
                           Seitenrand liefe, wird er etwas kleiner –
                           die Originalgröße bleibt sonst unangetastet. */
                        try {
                          var avail = page.getWidth() - line.x - 16;
                          var wNew = fnt.widthOfTextAtSize(txt, size);
                          if (wNew > avail && avail > 30) size = Math.max(4, size * (avail / wNew));
                        } catch (e2) { /* Messen ist Zusatz, nie Abbruchgrund */ }
                        page.drawText(txt, {
                          x: line.x, y: line.y, size: size,
                          font: fnt, color: rgbOf(line.color, black)
                        });
                      }
                    }
                  } catch (e) { /* einzelne Zeile überspringen, Rest bleibt */ }
                });
              });
              return doc.save();
            });
          }).catch(function (err) {
            if (window.console) console.warn("Textebene konnte nicht eingebettet werden:", err);
            return bytes;
          });
        }

        setOcr("idle", "OCR nicht gestartet");

        /* ---------------- UI refresh ---------------- */
        function renumber() {
          pages.forEach(function (p, i) {
            var c = cardEl(p.id);
            if (c) c.querySelector(".pos").textContent = i + 1;
          });
        }
        function refreshStats() {
          els.statFiles.textContent = files.size;
          els.statPages.textContent = pages.length;
          els.statSel.textContent = selected.size;
          els.statSelWrap.hidden = selected.size === 0;
          var has = pages.length > 0;
          var hasSel = selected.size > 0;
          els.btnBlank.disabled = !has;
          els.btnSelectAll.disabled = !has;
          els.btnDownload.disabled = !has;
          els.btnRotateSel.disabled = !hasSel;
          els.btnDeleteSel.disabled = !hasSel;
          els.btnExtract.disabled = !hasSel;
          document.getElementById("selAllLabel").textContent =
            (has && selected.size === pages.length) ? "Auswahl aufheben" : "Alle auswählen";
        }
        function refreshChips() {
          els.chips.innerHTML = "";
          files.forEach(function (f) {
            var chip = document.createElement("span");
            chip.className = "chip";
            var nm = document.createElement("span"); nm.className = "nm"; nm.textContent = f.name; nm.title = f.name;
            var ct = document.createElement("span"); ct.className = "ct"; ct.textContent = f.pageCount + (f.pageCount === 1 ? " Seite" : " Seiten");
            var rm = document.createElement("button");
            rm.type = "button"; rm.innerHTML = ICONS.x;
            rm.setAttribute("aria-label", f.name + " entfernen");
            rm.title = "Datei und ihre Seiten entfernen";
            rm.addEventListener("click", function () { removeFile(f.id); });
            chip.appendChild(nm); chip.appendChild(ct); chip.appendChild(rm);
            els.chips.appendChild(chip);
          });
          els.filebar.classList.toggle("show", files.size > 0 && currentView !== "home");
        }
        function refresh() {
          var has = pages.length > 0 || files.size > 0;
          applyView();
          if (has) {
            /* Textdaten neuer Seiten automatisch nachladen; steht der
               Nutzer gerade in einem Textfeld, wird die Liste nicht
               unter seinen Fingern neu aufgebaut. */
            var missing = pages.some(function (pg) { return !pageTextData[pg.id]; });
            var active = document.activeElement;
            var typing = active && els.txPanel.contains(active) && active.tagName === "INPUT";
            if (missing) loadAllPageData();
            else if (!typing) renderTxPages();
          }
          if (!has) { els.filebar.classList.remove("show"); els.dlpanel.hidden = true; }
          /* append cards for pages that don't have one yet */
          pages.forEach(function (p) {
            if (!cardEl(p.id)) els.grid.appendChild(buildCard(p));
          });
          renumber();
          refreshChips();
          refreshStats();
        }

        if (!PDFLib) {
          toast("Die PDF-Bibliothek konnte nicht geladen werden. Bitte Seite neu laden.", true);
        }
        refresh();
      })();
    
